"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["27994"],{63805(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.documento_exigido_base_legal.abrangencia_obrigatoria","status":422,"titulo":"A abrang\xeancia da base legal \xe9 obrigat\xf3ria"},"descricao":{"codigo":"uniplus.selecao.documento_exigido_base_legal.abrangencia_obrigatoria","requisitos":["UNI-REQ-0059"],"oQueAconteceu":["Cada base legal de um documento exigido declara a abrang\xeancia da norma, que \xe9 uma de cinco:\\n`FEDERAL`, `ESTADUAL`, `MUNICIPAL`, `INTERNA_NORMA` ou `INTERNA_EDITAL`. A base legal apontada\\nveio sem abrang\xeancia, ou com um valor que n\xe3o \xe9 nenhum desses.","Na defini\xe7\xe3o dos documentos exigidos e na aplica\xe7\xe3o de um modelo de formul\xe1rio, \xe9 uma\\nconfer\xeancia de forma. Ela examina cada base legal do documento, e os tr\xeas defeitos poss\xedveis\\nde uma mesma base (refer\xeancia, abrang\xeancia e status) aparecem juntos; a confer\xeancia para na\\nprimeira exig\xeancia que tem defeito. O campo apontado na resposta traz a posi\xe7\xe3o da base legal\\nna lista.","Para a base legal de um grupo de alternativas (OU), o erro correspondente \xe9\\n[`uniplus.selecao.base_legal_da_comprovacao.abrangencia_obrigatoria`](/erros/uniplus.selecao.base_legal_da_comprovacao.abrangencia_obrigatoria)."],"comoResolver":["Informe uma das cinco abrang\xeancias na base legal apontada. Na aplica\xe7\xe3o de um modelo de\\nformul\xe1rio, a base legal vem do modelo: escolha outro modelo ou pe\xe7a a revis\xe3o dele."],"ondeAparece":["Defini\xe7\xe3o de documentos exigidos do processo seletivo","Aplica\xe7\xe3o de modelo de formul\xe1rio"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Documento exigido base legal"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"0258f07cac6c9b7f9d70290a4b0385549eb99572"}}')}}]);